P.arrow=function(x1,y1,x2,y2){return '<line x1="'+n1(x1)+'" y1="'+n1(y1)+'" x2="'+n1(x2)+'" y2="'+n1(y2)+'" stroke="'+this.dim+'" stroke-width="1.1" marker-end="url(#'+this.id+'a)"/>'};
