 [-1,1].forEach(function(k){g.add('<line x1="'+n1(sx)+'" y1="'+n1(cy+k*rTm)+'" x2="'+n1(wx+swv+3)+'" y2="'+n1(cy+k*rTm)+'" stroke="'+LC+'" stroke-width="1"/>')});
